pub(crate) fn normalize_unicode_symbol(mode: Mode, text: &str) -> String {
    if text.is_empty() {
        return text.to_string();
    }
    let first = &text[..text.char_indices().nth(1).map_or(text.len(), |(i, _)| i)];
    if let Some(decomposition) = unicode_symbol_decompositions().get(first) {
        if lookup_symbol(mode, first).is_none() {
            return format!("{decomposition}{}", &text[first.len()..]);
        }
    }
    text.to_string()
}

pub(crate) fn trailing_combining_mark_start(text: &str) -> Option<usize> {
    let chars: Vec<char> = text.chars().collect();
    let mut start = chars.len();
    while start > 0 && is_combining_diacritical_mark(chars[start - 1]) {
        start -= 1;
    }
    if start != chars.len() {
        Some(start)
    } else {
        None
    }
}

pub(crate) fn unicode_accent_command(mode: Mode, accent: &str) -> Option<String> {
    let result = match accent {
        "\u{301}" => Some(if mode == Mode::Math { "\\acute" } else { "\\'" }),
        "\u{300}" => Some(if mode == Mode::Math { "\\grave" } else { "\\`" }),
        "\u{308}" => Some(if mode == Mode::Math { "\\ddot" } else { "\\\"" }),
        "\u{303}" => Some(if mode == Mode::Math { "\\tilde" } else { "\\~" }),
        "\u{304}" => Some(if mode == Mode::Math { "\\bar" } else { "\\=" }),
        "\u{306}" => Some(if mode == Mode::Math { "\\breve" } else { "\\u" }),
        "\u{30C}" => Some(if mode == Mode::Math { "\\check" } else { "\\v" }),
        "\u{302}" => Some(if mode == Mode::Math { "\\hat" } else { "\\^" }),
        "\u{307}" => Some(if mode == Mode::Math { "\\dot" } else { "\\." }),
        "\u{30A}" => Some(if mode == Mode::Math {
            "\\mathring"
        } else {
            "\\r"
        }),
        "\u{30B}" => Some("\\H"),
        "\u{327}" => Some("\\c"),
        _ => None,
    };
    result.map(ToString::to_string)
}
